package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();Flower f=s.get(Flower.class,"2");if(f==null){f=new Flower();f.setFlowerId("2");f.setFlowerName("Carnation");f.setColor("White");f.setPrice(new java.math.BigDecimal("15"));s.persist(f);t.commit();System.out.println("Flower id 2 was created for the assignment test.");}else{t.commit();System.out.println(f.getFlowerId()+" "+f.getFlowerName()+" "+f.getColor()+" "+f.getPrice());}}HibernateUtil.getSessionFactory().close();}}